package ai

import (
	"github.com/Vadman97/GolangChessAI/pkg/chessai/color"
	"testing"
)

func TestStockfishClassicNg2BlocksBishopContact(t *testing.T) {
	bishop := boardFromFENPlacement(t, "r2qkbr1/1p3p1p/p1p1p3/4P3/1nPB3N/1P4Pb/P2Q1P1P/RN3RK1")
	defended := boardFromFENPlacement(t, "r2qkbr1/1p3p1p/p1p1p3/4P3/1nPB4/1P4Pb/P2Q1PNP/RN3RK1")
	queen := boardFromFENPlacement(t, "r3kbr1/1p3p1p/p1p1p3/4P3/1nPB2bq/1P4P1/P2Q1P1P/RN3RK1")
	bh3 := evaluateStockfishClassicScore(bishop, color.Black)
	ng2 := evaluateStockfishClassicScore(defended, color.Black)
	qh4 := evaluateStockfishClassicScore(queen, color.Black)
	// In qkmR1kyN, ...Bh3 allows Ng2, while ...Qxh4 offers the queen to
	// deflect g3 and uncover ...Be2. SF22 scores the choices about +30/+310.
	if ng2 >= qh4 || bh3-ng2 < 150 || ng2 >= 150 {
		t.Fatalf("Ng2 must restrain Bh3's contact pressure: Bh3=%d Ng2=%d Qxh4=%d", bh3, ng2, qh4)
	}
	if white := evaluateStockfishClassicScore(defended, color.White); white != -ng2 {
		t.Fatal("king pressure broke side-to-move symmetry")
	}
}

func TestStockfishClassicDefendedKingSquareStillCountsAsCheck(t *testing.T) {
	guarded := boardFromFENPlacement(t, "6k1/8/1q6/8/8/5NP1/4nP1P/6K1")
	unguarded := boardFromFENPlacement(t, "6k1/8/1q6/8/8/6P1/4nP1P/6K1")
	if !guarded.IsKingInCheck(color.White) || !unguarded.IsKingInCheck(color.White) {
		t.Fatal("knight must check both kings")
	}
	with := kingDangerEvalForTest(guarded).kingDanger(color.White)
	without := kingDangerEvalForTest(unguarded).kingDanger(color.White)
	if without.mg-with.mg > 200 {
		t.Fatalf("friendly protection of king square must not erase a check: guarded=%+v unguarded=%+v", with, without)
	}
}

