func TestABDADASeesQueenSacrificeDiscoveredCheck(t *testing.T) {
	const fen = "r2qkbr1/1p3p1p/p1p1p3/4P3/1nPB2bN/1P4P1/P2Q1P1P/RN3RK1 b q - 0 15"
	scores := map[string]int{}
	for _, uci := range []string{"g4h3", "d8h4"} {
		parsed, err := analysis.ParseFEN(fen)
		if err != nil {
			t.Fatal(err)
		}
		parsed.Board.CacheGetAllMoves = false
		parsed.Board.CacheGetAllAttackableMoves = false
		algorithm := &ai.ABDADA{NumThreads: 1}
		player := ai.NewAIPlayer(parsed.Active, algorithm)
		player.TranspositionTableEnabled = true
		player.PrintInfo = false
		player.Debug = false
		move, err := analysis.MatchUCIMove(parsed.Board, parsed.Active, parsed.Previous, uci)
		if err != nil {
			t.Fatal(err)
		}
		scores[uci] = algorithm.ScoreRootMove(player, parsed.Board, move, 6).Score
	}
	t.Logf("Bh3=%d Qxh4=%d", scores["g4h3"], scores["d8h4"])
	// Qxh4 gxh4 Be2+ uncovers the g8 rook. Reducing Be2 because the
	// bishop itself gives no check misses the deflection that wins material.
	if scores["d8h4"] < 150 || scores["d8h4"] <= scores["g4h3"] {
		t.Fatalf("expected winning Qxh4 deflection over Bh3: %v", scores)
	}
}

