// Passed-pawn base bonus by relative rank (0..7). A passed pawn is never on relrank 0/7.
var sfPassedRank = [8]sfScore{
	{}, {}, {10, 28}, {17, 33}, {15, 41}, {62, 72}, {168, 177}, {},
